using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Main Menu PREFAB (Assets/_Project/Prefabs/UI/MainMenu.prefab,
/// generated by FrontendScreenPrefabs — Tools > MusicGame > UI > Build All UI Prefabs — and edited by hand
/// from then on). MainMenuController spawns it (UIPrefabLibrarySO.mainMenu), only READS these references
/// and wires interaction — it never creates or lays out this UI itself. The visible buttons are re-stacked
/// at runtime from PLAY's slot downward (step = button height + buttonStackGap) in this order:
/// PLAY, RIVALS, PROGRESSION, SETTINGS, QUIT (QUIT is hidden on mobile).
/// </summary>
public class MainMenuView : MonoBehaviour
{
    [Header("Root")]
    public GameObject root;
    public TextMeshProUGUI titleText;
    [Tooltip("Persistent level / XP / lives summary under the title (hidden until a progression save exists).")]
    public TextMeshProUGUI profileText;
    [Tooltip("\"Catalog complete\" / load failure line (hidden while empty).")]
    public TextMeshProUGUI menuStatusText;

    [Header("Buttons")]
    public Button      playButton;
    [Tooltip("PLAY on first launch, CONTINUE once a progression save exists (set at runtime).")]
    public TextMeshProUGUI playButtonLabel;
    public Button      rivalsButton;
    public Button      progressionButton;
    public Button      settingsButton;
    public TextMeshProUGUI settingsButtonLabel;
    public Button      quitButton;
    public TextMeshProUGUI quitButtonLabel;
    [Tooltip("Vertical gap between stacked menu buttons.")]
    public float       buttonStackGap = 18f;

    [Header("Settings panel")]
    public GameObject  settingsPanel;
    public TextMeshProUGUI settingsTitleText;
    public TextMeshProUGUI volumeLabelText;
    public Slider      volumeSlider;
    public Button      closeButton;
    public TextMeshProUGUI closeButtonLabel;
    [Tooltip("Nested LanguageSelector prefab inside the settings panel (the panel is already sized for it).")]
    public LanguageSelectorView languageSelector;
}
